// #region 🔖Header
// 💻 compose/algorithms/.storybook/preview.ts
// Specs: Match .elements/ui Storybook globals and decorators.
// Summary: Defines global Storybook preview parameters for algorithms.
// 2026 Ueli Saluz <ueli@semio-tech.com>
// #endregion 🔖Header

import type { Preview } from "@storybook/react-vite";
import { withLevel } from "./withLevel";
import { withTheme } from "./withTheme";
import { AlgorithmLanguage, withLanguage } from "./withLanguage";

import "../../ui/globals.css";

enum Theme {
  SYSTEM = "system",
  LIGHT = "light",
  DARK = "dark",
}

const preview: Preview = {
  parameters: {
    controls: {
      matchers: {
        color: /(background|color)$/i,
        date: /Date$/i,
      },
    },
  },
  globalTypes: {
    theme: {
      description: "Global theme for components",
      toolbar: {
        title: "Theme",
        icon: "circlehollow",
        items: [
          { value: Theme.SYSTEM, title: "System", icon: "browser" },
          { value: Theme.LIGHT, title: "Light", icon: "sun" },
          { value: Theme.DARK, title: "Dark", icon: "moon" },
        ],
        dynamicTitle: true,
      },
    },
    language: {
      description: "Global implementation language for algorithm execution",
      toolbar: {
        title: "Language",
        icon: "circlehollow",
        items: [
          { value: AlgorithmLanguage.TS, title: "TypeScript", icon: "code" },
          { value: AlgorithmLanguage.PYTHON, title: "Python", icon: "python" },
          { value: AlgorithmLanguage.RUST, title: "Rust", icon: "code-fork" },
          { value: AlgorithmLanguage.GO, title: "Go", icon: "terminal" },
        ],
        dynamicTitle: true,
      },
    },
  },
  initialGlobals: {
    theme: Theme.SYSTEM,
    language: AlgorithmLanguage.TS,
  },
  decorators: [withLevel, withLanguage, withTheme],
  tags: ["autodocs"],
};

export default preview;

// #region 🔖Header
// 💻 compose/algorithms/.storybook/withLanguage.tsx
// Specs: Provide a global Storybook toolbar selector for algorithm implementation language.
// Summary: Wraps stories with a LanguageProvider and exposes `useAlgorithmLanguage()` for story UI.
// 2026 Ueli Saluz <ueli@semio-tech.com>
// #endregion 🔖Header

import type { Decorator } from "@storybook/react";
import * as React from "react";

export enum AlgorithmLanguage {
  TS = "ts",
  PYTHON = "python",
  RUST = "rust",
  GO = "go",
}

export type AlgorithmLanguageValue = (typeof AlgorithmLanguage)[keyof typeof AlgorithmLanguage];

const AlgorithmLanguageContext = React.createContext<AlgorithmLanguageValue>(AlgorithmLanguage.TS);

export function useAlgorithmLanguage(): AlgorithmLanguageValue {
  return React.useContext(AlgorithmLanguageContext);
}

export const AlgorithmLanguageProvider: React.FC<{
  language: AlgorithmLanguageValue;
  children: React.ReactNode;
}> = ({ language, children }) => {
  return <AlgorithmLanguageContext.Provider value={language}>{children}</AlgorithmLanguageContext.Provider>;
};

export const withLanguage: Decorator = (Story, context) => {
  const language = (context.globals.language as AlgorithmLanguageValue | undefined) ?? AlgorithmLanguage.TS;
  return (
    <AlgorithmLanguageProvider language={language}>
      <Story />
    </AlgorithmLanguageProvider>
  );
};

// #region 🔖Header
// 💻 compose/algorithms/.storybook/stories/Drag.stories.tsx
// Specs: Uses the AlgorithmApp shell with VEC_INPUT, PIECES_SELECTION_INPUT, DESIGN_DIFF_OUTPUT, DESIGN_OUTPUT windows.
// Summary: Drag story using real Diagram-based algorithm windows from @compose/ui.
// 2026 Ueli Saluz <ueli@semio-tech.com>
// #endregion 🔖Header

import { applyDesignDiff, flattenDesign } from "@semio-tech/compose-js";
import type { Meta, StoryObj } from "@storybook/react";
import * as React from "react";

import { AlgorithmApp, type AlgorithmContextValue, type AlgorithmWindowDef, WindowKind } from "../../index";
import { useAlgorithmLanguage } from "../withLanguage";

import metabolismKit from "../../../assets/compose/metabolism.kit.compose.json";

const nakaginCapsuleTowerDesignGuid = "9a890dd4-0a9c-48ac-920a-9e62666465ef";
const rawDesign = (metabolismKit.designs ?? []).find((d: any) => d.guid === nakaginCapsuleTowerDesignGuid) as any;
const flattenChange = flattenDesign(metabolismKit as any, rawDesign.guid);
const baseDesign = applyDesignDiff(rawDesign, { pieces: flattenChange.forward.pieces }) as any;

const WINDOWS: AlgorithmWindowDef[] = [
  { id: "drag-vec", kind: WindowKind.VEC_INPUT, label: "Vec" },
  { id: "drag-input", kind: WindowKind.PIECES_SELECTION_INPUT, label: "Input" },
  { id: "drag-diff", kind: WindowKind.DESIGN_DIFF_OUTPUT, label: "Diff" },
  { id: "drag-output", kind: WindowKind.DESIGN_OUTPUT, label: "Output" },
];

function DragFrame() {
  const language = useAlgorithmLanguage();
  const kit = metabolismKit as any;
  const initialSelection = React.useMemo(() => (baseDesign?.pieces ?? []).slice(0, 3).map((piece: any) => piece.guid), []);
  const [selectedPieceGuids, setSelectedPieceGuids] = React.useState<string[]>(initialSelection);
  const [vec, setVec] = React.useState({ u: 1, v: -2 });

  const context: AlgorithmContextValue = React.useMemo(
    () => ({
      kit,
      design: baseDesign,
      vec,
      onVecChange: setVec,
      vecMin: { u: -10, v: -10 },
      vecMax: { u: 10, v: 10 },
      selectedPieceGuids,
      onSelectedPieceGuidsChange: setSelectedPieceGuids,
      designDiff: {
        pieces: { updated: selectedPieceGuids.map((guid) => ({ piece: { guid }, diff: { center: { ...vec }, language } })) },
        connections: { updated: [] },
      },
      outputDesign: baseDesign,
    }),
    [baseDesign, kit, language, selectedPieceGuids, vec],
  );

  return <AlgorithmApp id="drag" label="Drag" windows={WINDOWS} context={context} className="h-full w-full" />;
}

const meta = {
  title: "compose-algorithms/Drag",
  parameters: { layout: "fullscreen" },
  tags: ["autodocs"],
} satisfies Meta;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = { render: () => <DragFrame /> };

